"""Focused local interface for blind, independent training-label review."""

REVIEW_DASHBOARD_HTML = r"""<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Support policy review desk</title>
  <link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'%3E%3Crect width='32' height='32' rx='4' fill='%2317212b'/%3E%3Cpath d='M8 9h16v3H8zm0 6h16v3H8zm0 6h10v3H8z' fill='%23fff'/%3E%3C/svg%3E">
  <style>
    :root{--canvas:#eef1f4;--paper:#fff;--ink:#17212b;--muted:#687482;--line:#d4dae1;--blue:#245a91;--blue-soft:#eaf1f8;--amber:#9b651b;--danger:#9e3939;--radius:6px;--body:"Segoe UI",Arial,sans-serif;--record:Georgia,"Times New Roman",serif;--mono:"Cascadia Code",Consolas,monospace}
    *{box-sizing:border-box}body{margin:0;background:var(--canvas);color:var(--ink);font-family:var(--body)}button,input,select,textarea{font:inherit}:focus-visible{outline:3px solid #245a9133;outline-offset:2px}
    header{background:#17212b;color:#fff;border-bottom:4px solid var(--blue)}.head{max-width:1240px;margin:auto;padding:18px 28px;display:flex;justify-content:space-between;align-items:center;gap:20px}.head h1{font:600 20px/1.2 var(--record);margin:0}.head p{margin:4px 0 0;color:#c8d0d8;font-size:12px}.reviewer{display:flex;align-items:center;gap:8px}.reviewer label{font-size:11px;color:#c8d0d8}.reviewer input{width:170px;padding:8px 10px;border:1px solid #52606d;border-radius:4px;background:#fff;color:var(--ink)}
    main{max-width:1240px;margin:22px auto;padding:0 28px 50px}.progress{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:14px;margin-bottom:16px}.progress strong{font:600 12px var(--mono)}.track{height:7px;background:#dce1e7}.fill{height:100%;width:0;background:var(--blue)}
    .desk{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(340px,.75fr);background:var(--paper);border:1px solid var(--line);border-radius:var(--radius);overflow:hidden}.case{padding:26px 30px;border-right:1px solid var(--line)}.case-number{font:700 11px var(--mono);color:var(--blue);letter-spacing:.06em;text-transform:uppercase}.case h2{font:600 25px/1.25 var(--record);margin:9px 0 22px}.turn{border-left:3px solid var(--line);padding:3px 0 3px 15px;margin:0 0 17px}.turn.agent{border-color:#9aacbd}.turn.current{border-color:var(--blue);background:var(--blue-soft);padding:13px 15px}.turn-label{font-size:10px;font-weight:750;letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}.turn p{font-size:14px;line-height:1.55;margin:6px 0 0;white-space:pre-wrap}.note{margin-top:24px;padding-top:16px;border-top:1px solid var(--line);font-size:11px;line-height:1.5;color:var(--muted)}
    form{padding:24px;background:#fafbfc}.field{margin-bottom:16px}.field label,.legend{display:block;margin-bottom:6px;font-size:11px;font-weight:700;color:#364352}.field select,.field textarea{width:100%;border:1px solid #bfc8d2;border-radius:4px;background:#fff;padding:9px 10px;color:var(--ink)}.field textarea{min-height:76px;resize:vertical}.choice{display:grid;grid-template-columns:1fr 1fr;gap:8px}.choice label{display:flex;gap:8px;align-items:center;padding:10px;border:1px solid var(--line);border-radius:4px;background:#fff;font-size:12px}.check{display:flex;gap:8px;align-items:flex-start;font-size:12px;line-height:1.4}.save{width:100%;border:1px solid #194b7c;border-radius:4px;background:var(--blue);color:#fff;padding:11px;font-weight:700}.save:disabled{opacity:.6}.error{display:none;color:var(--danger);font-size:12px;margin:10px 0}.complete{display:none;padding:60px;text-align:center}.complete h2{font:600 28px var(--record)}
    @media(max-width:850px){.head{align-items:flex-start;flex-direction:column}.desk{grid-template-columns:1fr}.case{border-right:0;border-bottom:1px solid var(--line)}main{padding:0 14px 40px}.head{padding:16px}.case,form{padding:20px}}
  </style>
</head>
<body>
<header><div class="head"><div><h1>Support policy review desk</h1><p>Independent labels · predictions hidden · source integrity checked on save</p><a href="/ratings" style="color:#dbe9f7;font-size:12px">Switch to generated-reply ratings</a></div><div class="reviewer"><label for="reviewer">Reviewer ID</label><input id="reviewer" autocomplete="off" placeholder="reviewer-a"></div></div></header>
<main>
  <div class="progress"><strong id="position">Enter a reviewer ID</strong><div class="track"><div id="fill" class="fill"></div></div><strong id="remaining">400 remaining</strong></div>
  <section id="desk" class="desk">
    <article class="case"><div id="caseNumber" class="case-number">Case —</div><h2>Read the conversation before assigning policy labels.</h2><div id="context"></div><div class="turn current"><span class="turn-label">Current customer message</span><p id="customer">Enter your reviewer ID above to begin.</p></div><div class="turn agent"><span class="turn-label">Historical AmazonHelp reply</span><p id="reply">Shown only as evidence for the resolution act, not as the escalation policy.</p></div><p class="note">Judge whether the case itself requires a specialist. Do not copy Amazon's historical channel choice automatically. Model predictions and weak labels are intentionally hidden.</p></article>
    <form id="form">
      <div class="field"><label for="intent">Primary intent</label><select id="intent" required></select></div>
      <fieldset class="field" style="border:0;padding:0"><span class="legend">Specialist required</span><div class="choice"><label><input type="radio" name="escalate" value="true" required> Yes</label><label><input type="radio" name="escalate" value="false"> No</label></div></fieldset>
      <div class="field"><label for="reason">Routing reason</label><select id="reason" required></select></div>
      <div class="field"><label for="act">Best next resolution act</label><select id="act" required></select></div>
      <label class="check"><input id="ambiguous" type="checkbox"> The evidence is genuinely ambiguous</label>
      <div class="field" style="margin-top:12px"><label for="notes">Review notes</label><textarea id="notes" placeholder="Required when marked ambiguous"></textarea></div>
      <div id="error" class="error"></div><button id="save" class="save" type="submit">Save label and open next case</button>
    </form>
  </section>
  <section id="complete" class="complete"><h2>Review queue complete</h2><p>This reviewer's labels were stored separately. Run adjudication only after the second reviewer finishes.</p></section>
</main>
<script>
  const el=id=>document.getElementById(id);let item=null;
  function options(id,values,prompt){const s=el(id);s.replaceChildren(new Option(prompt,""));values.forEach(v=>s.add(new Option(v.replaceAll("_"," "),v)))}
  function renderContext(text){const box=el("context");box.replaceChildren();if(!text)return;String(text).split("\n").forEach(line=>{const agent=line.startsWith("AGENT:");const div=document.createElement("div");div.className=`turn ${agent?"agent":""}`;const tag=document.createElement("span");tag.className="turn-label";tag.textContent=agent?"Earlier agent":"Earlier customer";const p=document.createElement("p");p.textContent=line.replace(/^(CUSTOMER|AGENT):\s*/,"");div.append(tag,p);box.append(div)})}
  async function load(){const reviewer=el("reviewer").value.trim();if(!reviewer)return;const response=await fetch(`/api/review/next?reviewer_id=${encodeURIComponent(reviewer)}`);const data=await response.json();if(!response.ok)throw new Error(data.detail||"Could not load review queue");if(data.complete){el("desk").style.display="none";el("complete").style.display="block";el("position").textContent=`${data.completed} of ${data.total}`;el("remaining").textContent="Complete";el("fill").style.width="100%";return}item=data;el("desk").style.display="grid";el("complete").style.display="none";el("caseNumber").textContent=`Case ${data.position} · ${data.inbound_id}`;el("customer").textContent=data.customer_text;el("reply").textContent=data.historical_reply;renderContext(data.conversation_context);options("intent",data.intent_options,"Select intent");options("reason",data.reason_options,"Select routing reason");options("act",data.act_options,"Select resolution act");el("form").reset();el("position").textContent=`${data.completed} of ${data.total} reviewed`;el("remaining").textContent=`${data.remaining} remaining`;el("fill").style.width=`${100*data.completed/data.total}%`}
  el("reviewer").addEventListener("change",()=>load().catch(showError));
  function showError(error){el("error").textContent=error.message;el("error").style.display="block"}
  el("form").addEventListener("submit",async event=>{event.preventDefault();el("error").style.display="none";const reviewer=el("reviewer").value.trim();const selected=document.querySelector('input[name="escalate"]:checked');if(!item||!selected)return showError(new Error("Complete every required field"));const body={reviewer_id:reviewer,inbound_id:item.inbound_id,source_sha256:item.source_sha256,reviewed_intent:el("intent").value,reviewed_escalate:selected.value==="true",reviewed_reason_code:el("reason").value,reviewed_resolution_act:el("act").value,ambiguous:el("ambiguous").checked,review_notes:el("notes").value};el("save").disabled=true;try{const response=await fetch("/api/review",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});const data=await response.json();if(!response.ok)throw new Error(data.detail||"Label was not saved");await load()}catch(error){showError(error)}finally{el("save").disabled=false}});
</script>
</body></html>"""
